/**
 * Command.Panel: the search row, the listbox and the status inside the palette, mounted with the panel so each opening starts from an empty query.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/command.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input, output } from '@angular/core'

import * as zag from '@zag-js/combobox'

import {
  Icon,
  MEMBER_PROVIDERS,
  Spread,
  cell,
  composingKey,
  derived,
  mergeParts,
  mountEffect,
  normalizeProps,
  setup,
  uniqueId,
  useDirection,
  useMachine,
  useMember,
  watchEffect,
  type Each,
  type IconProps,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/overlays/command.module.css'
import { Kbd } from '../structure/Kbd'
import { Skeleton } from '../structure/Skeleton'
import type { CommandItem } from './Command'

/** Command.Panel: the search row, the listbox and the status inside the palette, mounted with the panel so each opening starts from an empty query: the inputs it takes, by the React member's prop names. */
export interface CommandPanelProps {
  items: CommandItem[]
  placeholder: string
  escapeHint: string
  filter: 'contains' | false
  loading: boolean
  emptyMessage: string
}

/** Command.Panel: the search row, the listbox and the status inside the palette, mounted with the panel so each opening starts from an empty query. */
@Component({
  selector: 'pm-command-panel',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Spread, Icon, Kbd, Skeleton],
  // prettier-ignore
  template: `<!-- search -->
<div
[attr.class]="e1()"
><pm-icon
name="search"
size="md"
></pm-icon>
<!-- input -->
<input
[pmSpread]="e2()"
/>
<pm-kbd>{{ e3() }}</pm-kbd></div>
<!-- body -->
<div
[attr.class]="e4()"
data-dialog-part="body"
><!-- list -->
<ul
[pmSpread]="e5()"
>@for (run of e6(); track e7(run); let at = $index) {@if (e8(run)) {@for (item of e9(run); track e10(item)) {<!-- item -->
<li
[pmSpread]="e11(run, item)"
>@if (e12(run, item)) {<span
[attr.class]="e13(run, item)"
><pm-icon
[name]="e14(run, item)"
size="sm"
></pm-icon></span>}
<span
[attr.class]="e15(run)"
[attr.id]="e16(run, item)"
>{{ e17(run, item) }}</span>
@if (e18(run, item)) {<span
[attr.class]="e19(run, item)"
><pm-kbd>{{ e20(run, item) }}</pm-kbd></span>}</li>}} @else {<li
[attr.class]="e21(run)"
role="presentation"
><span
[pmSpread]="e22(run, at)"
>{{ e23(run) }}</span>
<ul
[pmSpread]="e24(run, at)"
>@for (item of e25(run); track e26(item)) {<!-- item -->
<li
[pmSpread]="e27(run, item)"
>@if (e28(run, item)) {<span
[attr.class]="e29(run, item)"
><pm-icon
[name]="e30(run, item)"
size="sm"
></pm-icon></span>}
<span
[attr.class]="e31(run)"
[attr.id]="e32(run, item)"
>{{ e33(run, item) }}</span>
@if (e34(run, item)) {<span
[attr.class]="e35(run, item)"
><pm-kbd>{{ e36(run, item) }}</pm-kbd></span>}</li>}</ul></li>}}</ul>
@if (e37()) {<div
[attr.class]="e38()"
aria-hidden="true"
>@for (skeleton of e39(); track e40(skeleton)) {<div
[attr.class]="e41()"
><pm-skeleton
textStep="sm"
></pm-skeleton></div>}</div>}
@if (e42()) {<div
[attr.class]="e43()"
aria-hidden="true"
>{{ e44() }}</div>}</div>
<div
[attr.class]="e45()"
role="status"
aria-live="polite"
>{{ e46() }}</div>`,
})
export class CommandPanel {
  readonly items = input.required<CommandPanelProps['items']>()
  readonly placeholder = input.required<CommandPanelProps['placeholder']>()
  readonly escapeHint = input.required<CommandPanelProps['escapeHint']>()
  readonly filter = input.required<CommandPanelProps['filter']>()
  readonly loading = input.required<CommandPanelProps['loading']>()
  readonly emptyMessage = input.required<CommandPanelProps['emptyMessage']>()
  readonly onQueryChange = output<string>({ alias: 'queryChange' })
  readonly onCommand = output<void>({ alias: 'command' })
  protected readonly $ = useMember({
    events: ['queryChange', 'command'],
    props: {
      items: () => this.items(),
      placeholder: () => this.placeholder(),
      escapeHint: () => this.escapeHint(),
      filter: () => this.filter(),
      loading: () => this.loading(),
      emptyMessage: () => this.emptyMessage(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly uid = uniqueId()
  protected readonly query = cell(() => '')
  protected readonly collator = derived(
    () => new Intl.Collator(undefined, { usage: 'search', sensitivity: 'base' }),
  )
  protected readonly needle = derived(() => this.query.value.normalize('NFC'))
  protected readonly matches = derived(
    () => (item: CommandItem) =>
      ((text: string) =>
        this.needle.value === '' ||
        Array.from({ length: Math.max(0, text.length - this.needle.value.length + 1) }, (_, at) =>
          text.slice(at, at + this.needle.value.length),
        ).some((part) => this.collator.value.compare(part, this.needle.value) === 0))(
        (item.keywords === undefined
          ? item.label
          : `${item.label} ${item.keywords.join(' ')}`
        ).normalize('NFC'),
      ),
  )
  protected readonly shown = derived(() =>
    this.$p.filter === false
      ? this.$p.items
      : this.$p.items.filter((item) => this.matches.value(item)),
  )
  protected readonly runs = derived(() =>
    this.shown.value.reduce(
      (into, item) => (
        item.group !== undefined && into.at(-1)?.[0]?.group === item.group
          ? into.at(-1)?.push(item)
          : into.push([item]),
        into
      ),
      [] as CommandItem[][],
    ),
  )
  protected readonly firstEnabled = derived(
    () => this.shown.value.find((item) => item.disabled !== true)?.id,
  )
  protected readonly showEmpty = derived(() => !this.$p.loading && this.shown.value.length === 0)
  protected readonly announcement = derived(() =>
    this.$p.loading
      ? 'Loading commands…'
      : this.shown.value.length === 0
        ? this.$p.emptyMessage
        : `${this.shown.value.length} commands`,
  )
  protected readonly documentDirection = useDirection()
  protected readonly service: { readonly value: zag.Service } = setup(() =>
    useMachine(
      zag.machine,
      () =>
        ({
          id: this.uid,
          dir: this.documentDirection(),
          collection: zag.collection({
            items: this.shown.value,
            itemToValue: (item) => item.id,
            itemToString: (item) => item.label,
            isItemDisabled: (item) => item.disabled === true,
          }),
          open: true,
          disableLayer: true,
          value: [],
          closeOnSelect: false,
          selectionBehavior: 'preserve' as const,
          allowCustomValue: true,
          inputBehavior: 'autohighlight' as const,
          placeholder: this.$p.placeholder,
          onInputValueChange: (details) => {
            void ((this.query.value = details.inputValue),
            this.$.emit(this.onQueryChange, 'onQueryChange', details.inputValue))
          },
          onSelect: (details) => {
            void (this.$p.items.find((item) => item.id === details.itemValue)?.onSelect(),
            this.$.emit(this.onCommand, 'onCommand'))
          },
        }) as Partial<zag.Props>,
    ),
  )
  protected readonly api: { readonly value: ReturnType<typeof zag.connect> } = derived(() =>
    zag.connect(this.service.value, normalizeProps),
  )

  constructor() {
    mountEffect(() => this.effect1())
    watchEffect(
      () => this.api.value.highlightedValue ?? this.firstEnabled.value,
      () => this.effect2(),
      true,
    )
  }

  protected e1() {
    return styles.search
  }

  protected h1($event: KeyboardEvent): void {
    if ($event.key === 'Escape' && !composingKey($event)) {
      this.api.value.setInputValue('')
    }
  }

  protected e2() {
    return mergeParts(this.api.value.getInputProps(), {
      class: styles.input,
      'aria-label': this.$p.placeholder,
      onKeydown: ($event: KeyboardEvent) => this.h1($event),
    })
  }

  protected e3() {
    return this.$p.escapeHint
  }

  protected e4() {
    return styles.body
  }

  protected e5() {
    return mergeParts(this.api.value.getContentProps(), {
      class: styles.listbox,
      hidden: undefined,
      'aria-labelledby': undefined,
      'aria-label': 'Suggestions',
    })
  }

  e6() {
    return this.runs.value
  }

  protected e7(run: Each<ReturnType<CommandPanel['e6']>>) {
    return run.map((item) => item.id).join(' ')
  }

  protected e8(run: Each<ReturnType<CommandPanel['e6']>>) {
    return run[0]?.group === undefined
  }

  e9(run: Each<ReturnType<CommandPanel['e6']>>) {
    if (!(run[0]?.group === undefined)) return undefined as never
    return run
  }

  protected e10(item: Each<ReturnType<CommandPanel['e9']>>) {
    return `${this.query.value}/${item.id}`
  }

  protected e11(
    run: Each<ReturnType<CommandPanel['e6']>>,
    item: Each<ReturnType<CommandPanel['e9']>>,
  ) {
    if (!(run[0]?.group === undefined)) return undefined as never
    return mergeParts(this.api.value.getItemProps({ item: item, persistFocus: true }), {
      class: styles.item,
      'aria-labelledby': `${this.uid}-label-${item.id}`,
    })
  }

  protected e12(
    run: Each<ReturnType<CommandPanel['e6']>>,
    item: Each<ReturnType<CommandPanel['e9']>>,
  ) {
    if (!(run[0]?.group === undefined)) return undefined as never
    return item.icon !== undefined
  }

  protected e13(
    run: Each<ReturnType<CommandPanel['e6']>>,
    item: Each<ReturnType<CommandPanel['e9']>>,
  ) {
    if (!(run[0]?.group === undefined)) return undefined as never
    if (!(item.icon !== undefined)) return undefined as never
    return styles.glyph
  }

  protected e14(
    run: Each<ReturnType<CommandPanel['e6']>>,
    item: Each<ReturnType<CommandPanel['e9']>>,
  ): IconProps['name'] {
    if (!(run[0]?.group === undefined)) return undefined as never
    if (!(item.icon !== undefined)) return undefined as never
    return item.icon
  }

  protected e15(run: Each<ReturnType<CommandPanel['e6']>>) {
    if (!(run[0]?.group === undefined)) return undefined as never
    return styles.label
  }

  protected e16(
    run: Each<ReturnType<CommandPanel['e6']>>,
    item: Each<ReturnType<CommandPanel['e9']>>,
  ) {
    if (!(run[0]?.group === undefined)) return undefined as never
    return `${this.uid}-label-${item.id}`
  }

  protected e17(
    run: Each<ReturnType<CommandPanel['e6']>>,
    item: Each<ReturnType<CommandPanel['e9']>>,
  ) {
    if (!(run[0]?.group === undefined)) return undefined as never
    return item.label
  }

  protected e18(
    run: Each<ReturnType<CommandPanel['e6']>>,
    item: Each<ReturnType<CommandPanel['e9']>>,
  ) {
    if (!(run[0]?.group === undefined)) return undefined as never
    return item.hint !== undefined
  }

  protected e19(
    run: Each<ReturnType<CommandPanel['e6']>>,
    item: Each<ReturnType<CommandPanel['e9']>>,
  ) {
    if (!(run[0]?.group === undefined)) return undefined as never
    if (!(item.hint !== undefined)) return undefined as never
    return styles.hint
  }

  protected e20(
    run: Each<ReturnType<CommandPanel['e6']>>,
    item: Each<ReturnType<CommandPanel['e9']>>,
  ) {
    if (!(run[0]?.group === undefined)) return undefined as never
    if (!(item.hint !== undefined)) return undefined as never
    return item.hint
  }

  protected e21(run: Each<ReturnType<CommandPanel['e6']>>) {
    if (run[0]?.group === undefined) return undefined as never
    return styles.section
  }

  protected e22(run: Each<ReturnType<CommandPanel['e6']>>, at: number) {
    if (run[0]?.group === undefined) return undefined as never
    return mergeParts(this.api.value.getItemGroupLabelProps({ htmlFor: `${at}` }), {
      class: styles.groupLabel,
    })
  }

  protected e23(run: Each<ReturnType<CommandPanel['e6']>>) {
    if (run[0]?.group === undefined) return undefined as never
    return run[0]?.group
  }

  protected e24(run: Each<ReturnType<CommandPanel['e6']>>, at: number) {
    if (run[0]?.group === undefined) return undefined as never
    return mergeParts(this.api.value.getItemGroupProps({ id: `${at}` }), { class: styles.group })
  }

  e25(run: Each<ReturnType<CommandPanel['e6']>>) {
    if (run[0]?.group === undefined) return undefined as never
    return run
  }

  protected e26(item: Each<ReturnType<CommandPanel['e25']>>) {
    return `${this.query.value}/${item.id}`
  }

  protected e27(
    run: Each<ReturnType<CommandPanel['e6']>>,
    item: Each<ReturnType<CommandPanel['e25']>>,
  ) {
    if (run[0]?.group === undefined) return undefined as never
    return mergeParts(this.api.value.getItemProps({ item: item, persistFocus: true }), {
      class: styles.item,
      'aria-labelledby': `${this.uid}-label-${item.id}`,
    })
  }

  protected e28(
    run: Each<ReturnType<CommandPanel['e6']>>,
    item: Each<ReturnType<CommandPanel['e25']>>,
  ) {
    if (run[0]?.group === undefined) return undefined as never
    return item.icon !== undefined
  }

  protected e29(
    run: Each<ReturnType<CommandPanel['e6']>>,
    item: Each<ReturnType<CommandPanel['e25']>>,
  ) {
    if (run[0]?.group === undefined) return undefined as never
    if (!(item.icon !== undefined)) return undefined as never
    return styles.glyph
  }

  protected e30(
    run: Each<ReturnType<CommandPanel['e6']>>,
    item: Each<ReturnType<CommandPanel['e25']>>,
  ): IconProps['name'] {
    if (run[0]?.group === undefined) return undefined as never
    if (!(item.icon !== undefined)) return undefined as never
    return item.icon
  }

  protected e31(run: Each<ReturnType<CommandPanel['e6']>>) {
    if (run[0]?.group === undefined) return undefined as never
    return styles.label
  }

  protected e32(
    run: Each<ReturnType<CommandPanel['e6']>>,
    item: Each<ReturnType<CommandPanel['e25']>>,
  ) {
    if (run[0]?.group === undefined) return undefined as never
    return `${this.uid}-label-${item.id}`
  }

  protected e33(
    run: Each<ReturnType<CommandPanel['e6']>>,
    item: Each<ReturnType<CommandPanel['e25']>>,
  ) {
    if (run[0]?.group === undefined) return undefined as never
    return item.label
  }

  protected e34(
    run: Each<ReturnType<CommandPanel['e6']>>,
    item: Each<ReturnType<CommandPanel['e25']>>,
  ) {
    if (run[0]?.group === undefined) return undefined as never
    return item.hint !== undefined
  }

  protected e35(
    run: Each<ReturnType<CommandPanel['e6']>>,
    item: Each<ReturnType<CommandPanel['e25']>>,
  ) {
    if (run[0]?.group === undefined) return undefined as never
    if (!(item.hint !== undefined)) return undefined as never
    return styles.hint
  }

  protected e36(
    run: Each<ReturnType<CommandPanel['e6']>>,
    item: Each<ReturnType<CommandPanel['e25']>>,
  ) {
    if (run[0]?.group === undefined) return undefined as never
    if (!(item.hint !== undefined)) return undefined as never
    return item.hint
  }

  protected e37() {
    return this.$p.loading
  }

  protected e38() {
    if (!this.$p.loading) return undefined as never
    return styles.rows
  }

  e39() {
    if (!this.$p.loading) return undefined as never
    return [0, 1, 2]
  }

  protected e40(skeleton: Each<ReturnType<CommandPanel['e39']>>) {
    return skeleton
  }

  protected e41() {
    if (!this.$p.loading) return undefined as never
    return styles.row
  }

  protected e42() {
    return this.showEmpty.value
  }

  protected e43() {
    if (!this.showEmpty.value) return undefined as never
    return styles.empty
  }

  protected e44() {
    if (!this.showEmpty.value) return undefined as never
    return this.$p.emptyMessage
  }

  protected e45() {
    return styles.status
  }

  protected e46() {
    return this.announcement.value
  }

  private effect1(): void {
    this.$.emit(this.onQueryChange, 'onQueryChange', this.query.value)
  }

  private effect2(): void {
    void (
      this.api.value.highlightedValue === null &&
      this.firstEnabled.value !== undefined &&
      this.api.value.setHighlightValue(this.firstEnabled.value)
    )
  }
}
